function completeExpandedProfession(p){return commonProfession({
  ...p,
  educationLength:p.educationLength||(p.university?'4 yıl + uygulama':'Kurs, sertifika veya uygulamalı deneyim'),
  finding:p.finding||`${p.name} için küçük bir portföy çalışması, staj veya giriş seviyesi deneyim iyi bir başlangıçtır.`,
  daily:p.daily||`${p.name} olarak araştırır, planlar, uygulama yapar ve ortaya çıkan sonucu düzenli geri bildirimle iyileştirirsin.`,
  why:p.why||`Merakını somut bir işe dönüştürmek, bu alanda farklı insanlarla veya sistemlerle birlikte üretmeni sağlar.`,
  challenge:p.challenge||`Güncel kalmak, düzenli pratik yapmak ve farklı beklentileri aynı iş içinde dengelemek gerekir.`,
  firstStep:p.firstStep||`${p.name} alanından küçük bir örnek iş seç, bir hafta içinde tamamla ve sonucunu kısa bir notla değerlendir.`,
  similar:p.similar&&p.similar.length?p.similar:['Kullanıcı araştırmacısı','Proje yöneticisi']
});}

